import{c as s,Q as n,j as l,m as o}from"./chunks/framework.rWdQudnF.js";const d=JSON.parse('{"title":"架构概述 练习题","description":"","frontmatter":{"title":"架构概述 练习题"},"headers":[],"relativePath":"综合知识/架构设计/软件架构概述/架构概述 练习题.md","filePath":"综合知识/架构设计/软件架构概述/架构概述 练习题.md","lastUpdated":null}'),r={name:"综合知识/架构设计/软件架构概述/架构概述 练习题.md"};function a(e,t,i,g,p,c){return n(),l("div",null,[...t[0]||(t[0]=[o(`<h3 id="软件架构核心概念" tabindex="-1">软件架构核心概念 <a class="header-anchor" href="#软件架构核心概念" aria-label="Permalink to &quot;软件架构核心概念&quot;">​</a></h3><p><strong>[Q1] 软件架构概念（软件架构设计活动）</strong></p><p>软件架构设计包括提出架构模型、产生架构设计和进行设计评审等活动，是一个迭代的过程。架构设计主要关注软件组件的结构、属性和( )，并通过多种(请作答此空)_ 全面描述特定系统的架构。</p><ul><li><strong>A.</strong> 对象</li><li><strong>B.</strong> 代码</li><li><strong>C.</strong> 文档</li><li><strong>D.</strong> 视图</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q2] 软件架构概念（架构设计的目标）</strong></p><p>The objective of (请作答此空) is to determine what parts of the application software will be assigned to what hardware.</p><ul><li><strong>A.</strong> architecture design</li><li><strong>B.</strong> modular design</li><li><strong>C.</strong> physical design</li><li><strong>D.</strong> distribution design</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p><p>架构设计阶段的核心产出之一就是<strong>部署架构</strong>——把软件模块映射到物理节点上。比如：</p><p>一个电商系统：Web 服务器部署在 2 台云服务器上，数据库部署在 1 台独立数据库服务器上，缓存 Redis 部署在另一台服务器上——这就是架构设计阶段决定的。</p><p>其他选项</p><table tabindex="0"><thead><tr><th style="text-align:left;">选项</th><th style="text-align:left;">含义</th><th style="text-align:left;">为什么不对</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>B. modular design</strong></td><td style="text-align:left;">模块设计</td><td style="text-align:left;">关注如何把系统拆成模块/包，不关心硬件分配</td></tr><tr><td style="text-align:left;"><strong>C. physical design</strong></td><td style="text-align:left;">物理设计</td><td style="text-align:left;">范围更大：包含硬件选型、网络拓扑等，不止是软件→硬件分配</td></tr><tr><td style="text-align:left;"><strong>D. distribution design</strong></td><td style="text-align:left;">分布设计</td><td style="text-align:left;">是架构设计<strong>的一部分</strong>（分布式部署策略），不是题目问的完整目标</td></tr></tbody></table></div></details><hr><p><strong>[Q3] 软件架构概念（需求细化）</strong></p><p>The first step is to refine the ( 请作答此空) into more detailed requirements.</p><ul><li><strong>A.</strong> functional requirements</li><li><strong>B.</strong> nonfunctional requirements</li><li><strong>C.</strong> system constraint</li><li><strong>D.</strong> system operational environment</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>题干翻译：<strong>第一步是把 ___ 细化为更详细的需求。</strong></p><p>答案是 <strong>B. nonfunctional requirements（非功能性需求）</strong>。</p><p>为什么是非功能性需求？</p><p>软件工程中，需求分析的典型流程是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>功能性需求（功能列表）—— 相对明确，拆分即可  </span></span>
<span class="line"><span>        ↓  </span></span>
<span class="line"><span>非功能性需求（性能/安全/可用性等）—— 模糊宽泛，需要细化  </span></span>
<span class="line"><span>        ↓  </span></span>
<span class="line"><span>     架构设计</span></span></code></pre></div><p><strong>架构设计的第一步</strong>，就是要<strong>细化非功能性需求</strong>，因为：</p><ul><li>性能（响应时间 &lt; 200ms）、可用性（99.99%）、安全性、可扩展性……这些<strong>非功能性需求</strong>决定了架构选型</li><li>功能性需求更多影响<strong>模块划分</strong>，而非顶层架构决策</li></ul><p>其他选项为什么错？</p><table tabindex="0"><thead><tr><th style="text-align:left;">选项</th><th style="text-align:left;">含义</th><th style="text-align:left;">为什么不对</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A. functional requirements</strong></td><td style="text-align:left;">功能性需求</td><td style="text-align:left;">通常在架构设计前就已明确，细化的需求是更细的功能拆解，<strong>不是架构设计的第一步</strong></td></tr><tr><td style="text-align:left;"><strong>C. system constraint</strong></td><td style="text-align:left;">系统约束</td><td style="text-align:left;">是外部约束条件（如预算、法规），不是需要&quot;细化&quot;的东西</td></tr><tr><td style="text-align:left;"><strong>D. system operational environment</strong></td><td style="text-align:left;">系统运行环境</td><td style="text-align:left;">是运行环境描述，属于非功能性需求的一部分，不是第一步</td></tr></tbody></table><p>易错提醒</p><p>这道题和前面 Q1~Q2 构成一个逻辑链：</p><ol><li><strong>架构设计</strong>决定软件→硬件分配（Q2）</li><li>第一步：<strong>细化非功能性需求</strong>（Q3）</li><li>非功能性需求包括：<strong>性能、安全性、可用性</strong>等（Q19-Q20）</li></ol><p>💡 考官的陷阱：很多人本能选 <strong>functional requirements</strong>，因为觉得&quot;先搞清楚功能再设计架构&quot;。但架构设计的核心驱动力恰恰是<strong>非功能性需求</strong>——功能再全，性能不达标也是废的。</p></div></details><hr><p><strong>[Q4] 软件架构概念（数据访问逻辑）</strong></p><p>The second function is the（请作答此空）,the processing required to access data.</p><ul><li><strong>A.</strong> data persistence 数据持久化</li><li><strong>B.</strong> data access objects 数据访问对象</li><li><strong>C.</strong> database connection 数据库连接</li><li><strong>D.</strong> data access logic 数据访问逻辑</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>题干翻译：<strong>第二个功能是 ___，即访问数据所需的处理。</strong></p><p>答案是 <strong>D. data access logic（数据访问逻辑）</strong>。</p><h3 id="这个题的关键-知道「三个功能」是哪三个" tabindex="-1">这个题的关键：知道「三个功能」是哪三个 <a class="header-anchor" href="#这个题的关键-知道「三个功能」是哪三个" aria-label="Permalink to &quot;这个题的关键：知道「三个功能」是哪三个&quot;">​</a></h3><p>这道题来自一组连续题（Q11-Q14），描述应用系统的 <strong>三个核心功能层</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 数据存储（data storage）  </span></span>
<span class="line"><span>    → 存数据、取数据                       ← Q11</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 数据访问逻辑（data access logic）       ← 本题（Q4/Q12）  </span></span>
<span class="line"><span>    → 访问数据所需的处理逻辑  </span></span>
<span class="line"><span>      （查哪个表、怎么 join、where 条件拼装等）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 应用逻辑（application logic）  </span></span>
<span class="line"><span>    → DFD、用例、功能需求中描述的业务逻辑   ← Q13</span></span></code></pre></div><p><strong>数据访问逻辑</strong> 是介于&quot;纯存储&quot;和&quot;业务逻辑&quot;之间的中间层——它知道<strong>怎么去拿数据</strong>，但不负责业务规则。</p><h3 id="其他选项为什么错" tabindex="-1">其他选项为什么错？ <a class="header-anchor" href="#其他选项为什么错" aria-label="Permalink to &quot;其他选项为什么错？&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">选项</th><th style="text-align:left;">分析</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A. data persistence 数据持久化</strong></td><td style="text-align:left;">是一种机制/能力，而不是&quot;处理&quot;。题干问的是 <strong>processing（处理）</strong>，而非存储机制</td></tr><tr><td style="text-align:left;"><strong>B. data access objects 数据访问对象</strong></td><td style="text-align:left;">是<strong>实现模式</strong>（DAO 模式），是一种编码层面的设计，不是架构层面的三大功能之一</td></tr><tr><td style="text-align:left;"><strong>C. database connection 数据库连接</strong></td><td style="text-align:left;">是底层连接管理，属于基础设施，不是数据访问的&quot;处理逻辑&quot;</td></tr><tr><td style="text-align:left;"><strong>D. data access logic ✅</strong></td><td style="text-align:left;">正确定义：数据访问所需的处理过程（拼 SQL、ORM 查询、结果映射等）</td></tr></tbody></table><h3 id="易错点" tabindex="-1">易错点 <a class="header-anchor" href="#易错点" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><p>很多人看到&quot;访问数据&quot;就选 DAO（数据访问对象），但 <strong>DAO 是设计模式</strong>，而题目问的是<strong>系统软件架构的三个基本功能</strong>是什么——这在经典的架构设计教材中是固定三件套：</p><p><strong>Data Storage → Data Access Logic → Application Logic</strong></p></div></details><hr><p><strong>[Q5] 软件架构概念（构件关注点）</strong></p><p>软件架构设计主要关注软件构件的（ ）、属性和（请作答此空），并通过多种视图全面描述特定系统的架构。</p><ul><li><strong>A.</strong> 实现方式</li><li><strong>B.</strong> 交互作用</li><li><strong>C.</strong> 设计方案</li><li><strong>D.</strong> 测试方式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q6] 软件架构概念（错误描述）</strong></p><p>以下关于软件架构设计活动的描述，错误的是（）</p><ul><li><strong>A.</strong> 在建立软件架构的初期，一般需要选择一个合适的架构风格</li><li><strong>B.</strong> 将架构分析阶段已标识的构件映射到架构中，并分析这些构件之间的关系</li><li><strong>C.</strong> 软件架构设计活动将已标构件集成到软件架构中，设计并实现这些构件</li><li><strong>D.</strong> 一旦得到了详细的软件架构设计，需要邀请独立于系统开发的外部人员对系统进行评审</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>逐项分析</p><p>注意一下题干，这里是说：【软件架构设计活动】，那么选项需要找出设计活动错误的描述。</p><p>❌ C. 软件架构设计活动将已标构件集成到软件架构中，设计并实现这些构件</p><p><strong>错在哪？</strong> ——「实现」这两个字。</p><p>架构设计活动的边界是<strong>设计</strong>，不包含<strong>实现</strong>（编码/开发）。把构件设计出来、定义接口、描述交互——这是架构设计的事。但写代码实现构件是<strong>开发阶段</strong>的事。</p><p>完整的架构设计活动三步是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 提出架构模型 / 选架构风格  </span></span>
<span class="line"><span>② 产生架构设计（构件映射 + 关系分析）  </span></span>
<span class="line"><span>③ 设计评审</span></span>
<span class="line"><span></span></span>
<span class="line"><span>—— 到设计评审为止。实现？那是下游的事。</span></span></code></pre></div><p>✅ A. 在建立软件架构的初期，一般需要选择一个合适的架构风格</p><p>正确。架构风格（分层、微服务、事件驱动、管道-过滤器等）是顶层决策，初期必须选。</p><p>✅ B. 将架构分析阶段已标识的构件映射到架构中，并分析这些构件之间的关系</p><p>正确。这是架构设计的核心工作——<strong>构件映射 + 关系分析</strong>。</p><p>✅ D. 一旦得到了详细的软件架构设计，需要邀请独立于系统开发的外部人员对系统进行评审</p><p>正确。架构评审要求<strong>独立的外部专家</strong>参与，这是保证架构质量的关键手段。</p><hr><p>考点提炼</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>架构设计活动 = 建模 + 设计 + 评审  </span></span>
<span class="line"><span>                ↓  </span></span>
<span class="line"><span>          不包含「实现」</span></span></code></pre></div><p><strong>易错提醒</strong>：题目把「设计并实现」放在一起，很多人扫过去没注意&quot;实现&quot;两个字就选了。记住：<strong>架构师管设计，开发工程师管实现。</strong></p></div></details><hr><hr><h3 id="dssa-与构件" tabindex="-1">DSSA 与构件 <a class="header-anchor" href="#dssa-与构件" aria-label="Permalink to &quot;DSSA 与构件&quot;">​</a></h3><p><strong>[Q7] 软件架构概念（DSSA三层模型）</strong></p><p>DSSA通常是一个具有三个层次的系统模型，包括（请作答此空）环境、领域特定应用开发环境和应用执行环境。</p><ul><li><strong>A.</strong> 领域需求</li><li><strong>B.</strong> 领域开发</li><li><strong>C.</strong> 领域执行</li><li><strong>D.</strong> 领域应用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p><strong>答案是 B. 领域开发环境。</strong></p><hr><h3 id="dssa-三层模型" tabindex="-1">DSSA 三层模型 <a class="header-anchor" href="#dssa-三层模型" aria-label="Permalink to &quot;DSSA 三层模型&quot;">​</a></h3><p><strong>DSSA（Domain-Specific Software Architecture，特定领域软件架构）</strong> 的核心就是<strong>三层模型</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">层级</th><th style="text-align:left;">英文</th><th style="text-align:left;">作用</th></tr></thead><tbody><tr><td style="text-align:left;">① <strong>领域开发环境</strong></td><td style="text-align:left;">Domain Development Environment</td><td style="text-align:left;">定义领域的<strong>核心资产</strong>（领域模型、参考架构、可复用构件等）</td></tr><tr><td style="text-align:left;">② <strong>领域特定应用开发环境</strong></td><td style="text-align:left;">Domain-Specific Application Development Environment</td><td style="text-align:left;">基于领域资产，<strong>快速搭建具体应用</strong>的开发平台</td></tr><tr><td style="text-align:left;">③ <strong>应用执行环境</strong></td><td style="text-align:left;">Application Execution Environment</td><td style="text-align:left;">具体应用<strong>运行时的环境</strong>（运行时基础设施）</td></tr></tbody></table><p>这三个层次是一个<strong>从抽象到具体</strong>的漏斗：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>领域开发环境 (造工具)  </span></span>
<span class="line"><span>    ↓ 产出：领域模型、参考架构、通用构件  </span></span>
<span class="line"><span>领域特定应用开发环境 (用工具造应用)  </span></span>
<span class="line"><span>    ↓ 产出：具体应用系统  </span></span>
<span class="line"><span>应用执行环境 (跑应用)</span></span></code></pre></div><h3 id="记忆技巧" tabindex="-1">记忆技巧 <a class="header-anchor" href="#记忆技巧" aria-label="Permalink to &quot;记忆技巧&quot;">​</a></h3><p>口诀：<strong>「开发→开发→执行」</strong></p><p>三个词中两个是&quot;开发&quot;，但层级不同：</p><ol><li><strong>领域开发</strong> —— 为整个领域造&quot;积木&quot;</li><li><strong>领域特定应用开发</strong> —— 用积木搭具体应用</li><li><strong>应用执行</strong> —— 把搭好的东西跑起来</li></ol><h3 id="其他选项为什么错-1" tabindex="-1">其他选项为什么错？ <a class="header-anchor" href="#其他选项为什么错-1" aria-label="Permalink to &quot;其他选项为什么错？&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">选项</th><th style="text-align:left;">分析</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A. 领域需求</strong></td><td style="text-align:left;">需求是分析阶段的输入，不是 DSSA 三层之一</td></tr><tr><td style="text-align:left;"><strong>C. 领域执行</strong></td><td style="text-align:left;">没有&quot;领域执行&quot;这个概念。第三层是<strong>应用执行环境</strong>，不是领域执行</td></tr><tr><td style="text-align:left;"><strong>D. 领域应用</strong></td><td style="text-align:left;">DSSA 关注的是领域<strong>架构</strong>而非具体应用，且没有&quot;领域应用环境&quot;这一层</td></tr></tbody></table><h3 id="关联考点" tabindex="-1">关联考点 <a class="header-anchor" href="#关联考点" aria-label="Permalink to &quot;关联考点&quot;">​</a></h3><p>DSSA 还会考到的知识点：</p><ul><li><strong>DSSA 三角色</strong>：领域专家、领域架构师、领域开发人员</li><li><strong>DSSA 的活动</strong>：领域分析 → 领域设计 → 领域实现</li><li><strong>和架构风格的关系</strong>：DSSA 是一种<strong>特定领域的复用技术</strong>，不是架构风格本身（Q32 考过）</li></ul></div></details><hr><p><strong>[Q8] 软件架构概念</strong></p><p>在构件组装过程中需要检测并解决架构失配问题。其中 （1） 失配主要包括由于系统对构件基础设施、控制模型和数据模型的假设存在冲突引起的失配。</p><ul><li><strong>A.</strong> 构件</li><li><strong>B.</strong> 模型</li><li><strong>C.</strong> 协议</li><li><strong>D.</strong> 连接子</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p><p>区分这两个题目的关键在于理解<strong>架构失配</strong>中“构件”和“连接子”各自关注的冲突类型。</p><ul><li><strong>构件失配</strong>（Q8）：源于<strong>构件自身</strong>的假设冲突，例如对底层基础设施（操作系统、中间件）、控制模型（同步/异步、调用方式）或数据模型（数据结构、类型系统）的假设不一致。这些属于构件内部或构件与环境的固有属性差异。</li><li><strong>连接子失配</strong>（Q9）：源于<strong>构件之间交互</strong>的假设冲突，例如交互协议（消息顺序、超时机制、事务边界）或连接时数据格式（序列化格式、字节序、编码）不一致。这些属于连接线（即连接子）上需要协调的规则与格式差异。</li></ul><p><strong>记忆技巧</strong>：</p><ul><li>看到“基础设施、控制模型、数据模型” → 选<strong>构件</strong>（构件自身特征）。</li><li>看到“交互协议、数据格式” → 选<strong>连接子</strong>（构件间通信细节）。</li></ul></div></details><hr><p><strong>[Q9] 软件架构概念</strong></p><p>（2） 失配包括由于系统对构件交互协议、构件连接时数据格式的假设存在冲突引起的失配。</p><ul><li><strong>A.</strong> 构件</li><li><strong>B.</strong> 模型</li><li><strong>C.</strong> 协议</li><li><strong>D.</strong> 连接子</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q15] 软件架构概念（失配排除）</strong></p><p>在构件组装阶段失配问题主要不包括 （47） 。</p><ul><li><strong>A.</strong> 由构件引起的失配</li><li><strong>B.</strong> 由连接子引起的失配</li><li><strong>C.</strong> 由于系统成分对全局体系结构的假设存在冲突引起的失配</li><li><strong>D.</strong> 由构件操作不当引起的失配</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p><strong>背景知识</strong>：</p><p>软件架构失配（Architectural Mismatch）通常发生在构件组装时，由于构件之间或构件与系统环境之间的假设不一致导致。经典分类包括：</p><ul><li><strong>构件失配</strong>：构件对基础设施、控制模型、数据模型等的假设冲突。</li><li><strong>连接子失配</strong>：构件对交互协议、数据格式等的假设冲突。</li><li><strong>全局体系结构假设失配</strong>：系统组成部分对整体体系结构的约束或全局特性的假设冲突（如容错、安全、并发模型等）。</li></ul><p><strong>逐项分析</strong>：</p><ul><li><strong>A. 由构件引起的失配</strong> → 属于典型失配，如Q8所述。</li><li><strong>B. 由连接子引起的失配</strong> → 属于典型失配，如Q9所述。</li><li><strong>C. 由于系统成分对全局体系结构的假设存在冲突引起的失配</strong> → 也是典型失配，例如对全局控制流、数据共享方式的假设不一致。</li><li><strong>D. 由构件操作不当引起的失配</strong> → 这里的“操作不当”通常指运行时调用错误、参数类型不匹配、前置条件违反等，这些属于<strong>软件实现或使用错误</strong>，而非设计阶段或组装阶段的“架构失配”。架构失配关注的是<strong>静态假设冲突</strong>（如协议、模型、基础设施），而不是动态操作错误。因此，它不在主要失配类型之列。</li></ul></div></details><hr><h3 id="架构设计流程与需求分类-英文题" tabindex="-1">架构设计流程与需求分类（英文题） <a class="header-anchor" href="#架构设计流程与需求分类-英文题" aria-label="Permalink to &quot;架构设计流程与需求分类（英文题）&quot;">​</a></h3><p>The objective of <strong>(1)</strong> is to determine what parts of the application software will be assigned to what hardware. The major software components of the system being developed have to be identified and then allocated to the various hardware components on which the system will operate. All software systems can be divided into four basic functions. The first is <strong>(2)</strong>. Most information systems require data to be stored and retrieved, whether a small file, such as a memo produced by a word processor, or a large database, such as one that stores an organization’s accounting records. The second function is the <strong>(3)</strong>, the processing required to access data, which often means database queries in Structured Query Language. The third function is the <strong>(4)</strong>, which is the logic documented in the DFDs, use cases, and functional requirements. The fourth function is the presentation logic, the display of information to the user and the acceptance of the user’s commands. The three primary hardware components of a system are <strong>(5)</strong>.</p><hr><p><strong>[Q10] 软件架构概念（架构设计：硬件分配）</strong></p><p>The objective of （1） is to determine what parts of the application software will be assigned to what hardware.</p><ul><li><strong>A.</strong> architecture design</li><li><strong>B.</strong> modular design</li><li><strong>C.</strong> physical design</li><li><strong>D.</strong> distribution design</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p><p>翻译：</p><p>（1）的目标是确定应用软件的哪些部分将分配给哪些硬件。需要识别出正在开发的系统的主要软件组件，然后将其分配到系统运行所依赖的各种硬件组件上。所有软件系统都可以划分为四个基本功能。第一个功能是（2）。大多数信息系统都需要存储和检索数据，无论是像文字处理器生成的备忘录这样的小文件，还是像存储组织会计记录的大型数据库。第二个功能是（3），即访问数据所需的处理，这通常意味着用结构化查询语言进行数据库查询。第三个功能是（4），即记录在数据流图、用例和功能需求中的逻辑。第四个功能是表示逻辑，即向用户显示信息并接受用户命令。系统的三个主要硬件组件是（5）</p></div></details><hr><p><strong>[Q11] 软件架构概念（数据存储）</strong></p><p>The first is （2）. Most information systems require data to be stored and retrieved.</p><ul><li><strong>A.</strong> data access components</li><li><strong>B.</strong> database management system</li><li><strong>C.</strong> data storage</li><li><strong>D.</strong> data entities</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>根据句意“大多数信息系统需要存储和检索数据”，最直接对应的概念是<strong>数据存储（data storage）</strong>。因此正确答案是 <strong>C</strong>。</p></div></details><hr><p><strong>[Q12] 软件架构概念（数据访问逻辑）</strong></p><p>The second function is the （3）, the processing required to access data.</p><ul><li><strong>A.</strong> data persistence</li><li><strong>B.</strong> data access objects</li><li><strong>C.</strong> database connection</li><li><strong>D.</strong> data access logic</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>根据句子描述：“第二个功能是（3），即访问数据所需的处理。”</p><p>这里强调的是<strong>处理过程</strong>（processing），而非具体实现模式或连接。选项 <strong>D. data access logic</strong>（数据访问逻辑）最符合该定义。</p></div></details><hr><p><strong>[Q13] 软件架构概念（应用逻辑）</strong></p><p>The third function is the （4）, which is the logic documented in the DFDs, use cases,and functional requirements.</p><ul><li><strong>A.</strong> system requirements</li><li><strong>B.</strong> system architecture</li><li><strong>C.</strong> application logic</li><li><strong>D.</strong> application program</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>根据句子描述：“第三个功能是（4），即记录在DFD（数据流图）、用例和功能需求中的逻辑。”</p><p>这里明确指的是<strong>应用程序逻辑</strong>（application logic），即处理业务规则和功能需求的核心部分。</p><p>因此正确答案是 <strong>C</strong>。</p></div></details><hr><p><strong>[Q14] 软件架构概念（硬件构件）</strong></p><p>The three primary hardware components of a system are （5）.</p><ul><li><strong>A.</strong> computers,cables and network</li><li><strong>B.</strong> clients,servers,and network</li><li><strong>C.</strong> CPUs,memories and I/O devices</li><li><strong>D.</strong> CPUs,hard disks and I/O devices</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>在软件架构师考试中，常会区分“计算机体系结构”（CPU、内存、I/O）与“系统架构/分布式系统硬件架构”（客户端-服务器-网络）。本题明确提到“the three primary hardware components of a <strong>system</strong>”，结合前文关于分配软件到硬件的描述，这里的“system”是指<strong>信息系统</strong>或<strong>分布式系统</strong>，因此答案应选 B。</p><p>如果是单台计算机的话，可以考虑一下 C</p></div></details><hr><p>The architecture design specifies the overall architecture and the placement of software and hardware that will be used. Architecture design is a very complex process that is often left to experienced architecture designers and consultants.</p><p>The first step is to refine the (1) into more detailed requirements that are then employed to help select the architecture to be used and the software components to be placed on each device. In a (2), one also has to decide whether to use a two-tier, three-tier, or n-tier architecture. Then the requirements and the architect design are used to develop the hardware and software specification. There are four primary types of nonfunctional requirements that can be important in designing the architecture: (3) specify the operating environment(s) in which the system must perform and how those may change over time. (4) focus on the nonfunctional requirements issues such as response time, capacity, and reliability. (5) are the abilities to protect the information system from disruption and data loss, whether caused by an intentional act. Cultural and political requirements are specific to the countries in which the system will be used.</p><p><strong>[Q16] 软件架构概念（非功能性需求：第一步）</strong></p><p>The first step is to refine the （1） into more detailed requirements.</p><ul><li><strong>A.</strong> functional requirements</li><li><strong>B.</strong> nonfunctional requirements</li><li><strong>C.</strong> system constraint</li><li><strong>D.</strong> system operational environment</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>翻译：</p><p>架构设计规定了整体架构以及将要使用的软件和硬件的部署位置。架构设计是一个非常复杂的过程，通常由经验丰富的架构设计师和顾问完成。第一步是将（1）细化为更详细的需求，然后用于帮助选择要使用的架构以及部署在每台设备上的软件组件。在（2）中，还需要决定使用两层、三层还是 n 层架构。然后，利用这些需求和架构设计来制定硬件和软件规格说明。在设计架构时，有四类主要的非功能性需求可能非常重要：（3）规定了系统必须运行的操作环境以及这些环境随时间可能发生的变化。（4）关注响应时间、容量和可靠性等非功能性需求问题。（5）是指保护信息系统免受中断和数据丢失的能力，无论这些中断或丢失是由故意行为引起的。文化和政治需求则是系统使用所在国家/地区特有的需求。</p></div></details><hr><p><strong>[Q17] 软件架构概念（C/S架构）</strong></p><p>In a （2）, one also has to decide whether to use a two-tier, three-tier, or n-tier architecture.</p><ul><li><strong>A.</strong> client-based architecture</li><li><strong>B.</strong> server-based architecture</li><li><strong>C.</strong> network architecture</li><li><strong>D.</strong> client-server architecture</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>根据上下文，这里讨论的是<strong>客户端-服务器架构</strong>（client-server architecture），因为两层、三层和 n 层架构都是其具体实现形式。因此正确答案是 <strong>D</strong>。</p></div></details><hr><p><strong>[Q18] 软件架构概念（操作性需求）</strong></p><p>（3） specify the operating environment(s) in which the system must perform.</p><ul><li><strong>A.</strong> Operational requirements</li><li><strong>B.</strong> Speed requirement</li><li><strong>C.</strong> Access control requirements</li><li><strong>D.</strong> Customization requirements</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p><p>根据上下文，描述“指定系统必须运行的操作环境及其随时间的变化”的正是<strong>操作需求（Operational requirements）</strong>。因此正确答案是 <strong>A</strong>。</p><p>其他选项：速度需求、访问控制需求、定制化需求都不匹配。</p></div></details><hr><p><strong>[Q19] 软件架构概念（性能需求）</strong></p><p>（4） focus on the nonfunctional requirements issues such as response time, capacity, and reliability.</p><ul><li><strong>A.</strong> Environment requirements</li><li><strong>B.</strong> Maintainability requirements</li><li><strong>C.</strong> Performance requirements</li><li><strong>D.</strong> Virus control requirements</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>根据描述，关注响应时间、容量、可靠性等非功能性需求问题，正是<strong>性能需求（Performance requirements）</strong>。因此正确答案是 <strong>C</strong></p><p>其他选项</p><ul><li><strong>A. Environment requirements（环境需求）</strong><br> 关注系统运行所需的物理或软件环境，例如操作系统版本、网络带宽、硬件配置、温度湿度等。它不直接涉及响应时间、容量或可靠性。</li><li><strong>B. Maintainability requirements（可维护性需求）</strong><br> 关注系统便于修改、修复、升级的程度，例如模块化程度、日志记录、诊断接口等。与响应时间、容量没有直接关系。</li><li><strong>D. Virus control requirements（病毒控制需求）</strong><br> 属于安全需求的一类，侧重于防病毒、恶意软件检测与清除等。与性能指标（响应时间、容量、可靠性）不同。</li></ul></div></details><hr><p><strong>[Q20] 软件架构概念（安全性需求）</strong></p><p>（5） are the abilities to protect the information system from disruption and data loss.</p><ul><li><strong>A.</strong> Safety requirements</li><li><strong>B.</strong> Security requirements</li><li><strong>C.</strong> Data management requirements</li><li><strong>D.</strong> System requirements</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>根据题干描述：“保护信息系统免受中断和数据丢失的能力”，这明确指的是<strong>安全需求（Security requirements）</strong>。因此正确答案是 <strong>B</strong>。</p><p>其他选项解释：</p><ul><li><strong>A. Safety requirements（安全需求）</strong><br> 通常指<strong>人身安全</strong>或<strong>设备安全</strong>（如防止触电、机械伤害、防火等），与信息系统的数据丢失和中断防护不是同一概念。</li><li><strong>C. Data management requirements（数据管理需求）</strong><br> 侧重于数据的存储、备份、归档、生命周期管理等，不直接涵盖防护中断和故意破坏的能力。</li><li><strong>D. System requirements（系统需求）</strong><br> 范围太宽，包含功能性和非功能性需求，不能特指防护中断和数据丢失的能力。</li></ul><p>因此，正确答案是 <strong>B</strong>。</p></div></details><hr><h3 id="核心概念强化与专题" tabindex="-1">核心概念强化与专题 <a class="header-anchor" href="#核心概念强化与专题" aria-label="Permalink to &quot;核心概念强化与专题&quot;">​</a></h3><p><strong>[Q21] 软件架构概念（结构）</strong></p><p>软件架构设计主要关注软件构件的（1）、属性和（2）。</p><ul><li><strong>A.</strong> 功能</li><li><strong>B.</strong> 实现</li><li><strong>C.</strong> 组成元素</li><li><strong>D.</strong> 结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q22] 软件架构概念（交互作用）</strong></p><p>软件架构设计主要关注软件构件的（1）、属性和（2）。</p><ul><li><strong>A.</strong> 实现方式</li><li><strong>B.</strong> 交互作用</li><li><strong>C.</strong> 设计方案</li><li><strong>D.</strong> 测试方式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q23] 软件架构概念（ES vs 一般系统）</strong></p><p>专家系统（ES）与一般计算机系统的根本区别在于 （ ） 。</p><ul><li><strong>A.</strong> 处理数字与符号</li><li><strong>B.</strong> 处理确定性知识</li><li><strong>C.</strong> 解释推理过程</li><li><strong>D.</strong> 操作成本低廉</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q24] 软件架构概念（DSS）</strong></p><p>决策支持系统（DSS）主要用于解决 （ ） 。</p><ul><li><strong>A.</strong> 结构化问题</li><li><strong>B.</strong> 半结构化问题</li><li><strong>C.</strong> 日常事务处理</li><li><strong>D.</strong> 纯数据存储</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>DSS的定义：决策支持系统主要用于解决半结构化和非结构化问题，而非结构化问题。通常教材中说DSS解决半结构化问题。选项：A结构化问题（由MIS或TPS处理），B半结构化问题，C日常事务处理（TPS），D纯数据存储（数据库）。所以选B。</p><p>决策支持系统（DSS）主要辅助解决<strong>半结构化问题</strong>（如销售预测、预算规划等），这类问题既有一定的规律可循，又需要人的判断和灵活性。结构化问题通常由管理信息系统（MIS）或事务处理系统（TPS）处理；日常事务处理和纯数据存储则不属于DSS的核心定位。</p></div></details><hr><p><strong>[Q25] 软件架构概念（关注点）</strong></p><p>软件架构设计主要关注 （ ） 。</p><ul><li><strong>A.</strong> 构件的结构、属性及交互作用</li><li><strong>B.</strong> 编程语言语法规范</li><li><strong>C.</strong> 用户界面视觉设计</li><li><strong>D.</strong> 代码行数统计与优化</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><h3 id="架构设计生命周期" tabindex="-1">架构设计生命周期 <a class="header-anchor" href="#架构设计生命周期" aria-label="Permalink to &quot;架构设计生命周期&quot;">​</a></h3><p><strong>[Q26] 软件架构概念（设计阶段排除）</strong></p><p>在设计阶段，软件架构设计的研究主要不包括 （ ） 。</p><ul><li><strong>A.</strong> 软件架构模型的描述</li><li><strong>B.</strong> 软件架构模型的设计与分析方法</li><li><strong>C.</strong> 对软件架构设计经验的总结与复用</li><li><strong>D.</strong> 从现有系统中获得需要的构件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>软件架构设计阶段的研究重点包括：</p><ul><li><strong>A. 软件架构模型的描述</strong>（如架构视图、风格、模式）</li><li><strong>B. 软件架构模型的设计与分析方法</strong>（如质量属性场景、架构权衡分析方法）</li><li><strong>C. 对软件架构设计经验的总结与复用</strong>（如架构模式、参考架构）</li></ul><p>而 <strong>D. 从现有系统中获得需要的构件</strong> 更侧重于<strong>软件复用</strong>或<strong>构件获取</strong>，通常属于实现、集成或构件库管理阶段，不是架构设计阶段的核心研究内容。因此，该项不包括在内。</p></div></details><hr><p><strong>[Q27] 软件架构概念（架构设计作用）</strong></p><p>以下哪项不属于架构设计的主要作用（ ）。</p><ul><li><strong>A.</strong> 解决相对复杂的需求分析问题</li><li><strong>B.</strong> 解决非功能属性在系统占据重要位置的设计问题</li><li><strong>C.</strong> 解决系统代码实现的具体细节问题</li><li><strong>D.</strong> 解决生命周期长、扩展性需求高的系统整体结构问题</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q28] 软件架构概念（实现阶段研究）</strong></p><p>在软件架构的实现阶段研究中，以下哪项不属于主要研究方向（ ）。</p><ul><li><strong>A.</strong> 基于软件架构的开发过程支持</li><li><strong>B.</strong> 从软件架构向实现过渡的途径</li><li><strong>C.</strong> 基于软件架构的测试技术</li><li><strong>D.</strong> 软件架构的多视图表示</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>软件架构的实现阶段主要关注如何将架构设计转化为可运行的系统，包括：</p><ul><li><strong>A. 基于软件架构的开发过程支持</strong>（如迭代开发、架构驱动的开发流程）</li><li><strong>B. 从软件架构向实现过渡的途径</strong>（如架构映射、代码生成）</li><li><strong>C. 基于软件架构的测试技术</strong>（如架构符合性测试、构件集成测试）</li></ul><p>而 <strong>D. 软件架构的多视图表示</strong>（如逻辑视图、物理视图等）属于<strong>架构描述与设计阶段</strong>的研究内容，用于表达和沟通架构设计，而非实现阶段的核心方向。因此，该项不属于实现阶段的主要研究。</p></div></details><hr><p><strong>[Q29] 软件架构概念（需求→架构转换）</strong></p><p>在软件架构设计的需求阶段，关于需求模型向软件架构模型转换的主要关注点是（）。</p><ul><li><strong>A.</strong> 如何描述软件架构模型</li><li><strong>B.</strong> 如何分析软件架构质量属性</li><li><strong>C.</strong> 如何构建软件架构模型和保证可追踪性</li><li><strong>D.</strong> 如何选择合适的部署方案</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p><strong>解析</strong>：</p><p>在软件架构设计的需求阶段，核心任务是<strong>从需求模型（如用例、质量属性场景、约束）过渡到架构模型</strong>。这个转换过程中，主要关注两点：</p><ol><li><strong>如何构建软件架构模型</strong>：即如何将功能需求和非功能需求映射为构件、连接子、配置等架构元素。</li><li><strong>保证可追踪性</strong>：确保每个架构决策都能回溯到具体需求（尤其是质量属性场景），以便后续验证、评估和变更管理。</li></ol><ul><li><strong>A</strong>（如何描述软件架构模型）属于<strong>设计阶段</strong>的表示问题，而不是转换的关注点。</li><li><strong>B</strong>（如何分析软件架构质量属性）属于<strong>设计阶段</strong>的评估方法，是在模型构建之后进行。</li><li><strong>D</strong>（如何选择合适的部署方案）属于<strong>部署阶段</strong>的活动。</li></ul><p>因此，<strong>C</strong> 最准确地描述了需求阶段向架构模型转换时的核心关注点。</p></div></details><hr><p><strong>[Q30] 软件架构概念（设计阶段关注）</strong></p><p>在软件架构设计的研究中，设计阶段主要关注哪些方面（ ）。</p><ul><li><strong>A.</strong> 需求分析和用户反馈</li><li><strong>B.</strong> 软件架构模型描述、设计与分析方法</li><li><strong>C.</strong> 代码实现和单元测试</li><li><strong>D.</strong> 系统部署和性能优化</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q31] 软件架构概念（设计阶段）</strong></p><p>在软件架构设计生命周期中，哪个阶段主要关注软件架构模型的描述、设计与分析方法（ ）。</p><ul><li><strong>A.</strong> 需求分析阶段</li><li><strong>B.</strong> 设计阶段</li><li><strong>C.</strong> 实现阶段</li><li><strong>D.</strong> 构件组装阶段</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q32] 软件架构概念（重用设计经验）</strong></p><p>在软件体系结构设计中，用于总结和重用设计经验的主要技术包括（）。</p><ul><li><strong>A.</strong> 设计模式和框架</li><li><strong>B.</strong> 体系结构风格和DSSA</li><li><strong>C.</strong> UML图和原型设计</li><li><strong>D.</strong> 代码重构和单元测试</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p><strong>解析</strong>：</p><p>在软件体系结构设计中，总结和重用设计经验的主要技术包括：</p><ul><li><p><strong>体系结构风格</strong>（如分层、管道-过滤器、事件驱动等）是对一类相似问题的通用解决方案模板，可复用架构经验。</p></li><li><p><strong>DSSA（特定领域软件架构）</strong> 是针对特定领域（如航空、金融、医疗）总结出的参考架构，支持在该领域内大规模重用设计经验。</p></li><li><p><strong>A</strong>（设计模式和框架）更偏向<strong>详细设计</strong>和<strong>实现</strong>层面的重用，虽然也涉及经验总结，但不是最高层次的<strong>体系结构</strong>重用技术。</p></li><li><p><strong>C</strong>（UML图和原型设计）是建模和验证手段，并非专门用于总结和重用设计经验。</p></li><li><p><strong>D</strong>（代码重构和单元测试）属于<strong>实现与测试</strong>阶段的活动，与设计经验总结无关。</p></li></ul><p>因此，<strong>B</strong> 最符合题意。</p></div></details><hr><p><strong>[Q33] 软件架构概念（设计目标）</strong></p><p>软件架构设计的主要目标是获得一个满足什么需求的软件系统框架模型（ ）。</p><ul><li><strong>A.</strong> 只满足功能性需求</li><li><strong>B.</strong> 只满足非功能性需求</li><li><strong>C.</strong> 满足功能性需求和非功能性需求</li><li><strong>D.</strong> 满足用户界面需求</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q34] 软件架构概念（模型转换）</strong></p><p>在从软件需求模型向软件架构模型转换时，需要特别关注的两个核心问题是 （ ） 。</p><ul><li><strong>A.</strong> 如何估算项目成本和如何分配开发任务</li><li><strong>B.</strong> 如何根据需求模型构建架构模型，以及如何保证模型转换的可追踪性</li><li><strong>C.</strong> 如何选择编程语言和如何设计数据库表</li><li><strong>D.</strong> 如何进行用户验收测试和如何编写用户手册</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details>`,179)])])}const h=s(r,[["render",a]]);export{d as __pageData,h as default};
